# First, pull data. Then, work locally in R.

### Evictions db SQL queries ###

# Eviction Filings, 2020 - 2025, all
filings_20_25 &lt;- dbGetQuery(con, "
  SELECT DISTINCT(i.indexnumberid), fileddate, court
  FROM oca_index i
  WHERE i.fileddate &gt;= MAKE_DATE(2020,1,1) 
      AND i.fileddate &lt;= MAKE_DATE(2025,12,31)
      AND i.classification IN ('Holdover', 'Non-Payment')
      AND (i.propertytype = 'Residential' OR i.propertytype IS NULL);
")

# Eviction Filings, 2020 - 2025, with location
filings_20_25_sf &lt;- st_read(con, query = "
  SELECT DISTINCT(i.indexnumberid), fileddate, court,
    ST_Transform(a.geom, 2263) AS geom
  FROM oca_index i
  JOIN oca_addresses a ON i.indexnumberid = a.indexnumberid
  WHERE i.fileddate &gt;= MAKE_DATE(2020,1,1) 
      AND i.fileddate &lt;= MAKE_DATE(2025,12,31)
      AND i.classification IN ('Holdover', 'Non-Payment')
      AND (i.propertytype = 'Residential' OR i.propertytype IS NULL)
      AND a.geom IS NOT NULL;
")

# Executed Evictions, 2020 - 2025, all
executions_20_25 &lt;- dbGetQuery(con, "
  SELECT DISTINCT(i.indexnumberid), w.executiondate, i.court
  FROM oca_index i
  JOIN oca_warrants w ON i.indexnumberid = w.indexnumberid
  WHERE w.executiondate &gt;= MAKE_DATE(2020,1,1) 
    AND w.executiondate &lt;= MAKE_DATE(2025,12,31)
    AND i.classification IN ('Holdover', 'Non-Payment')
    AND (i.propertytype = 'Residential' OR i.propertytype IS NULL)
    AND w.executiondate IS NOT NULL;
")

# Executed Evictions, 2020 - 2025, with location
executions_20_25_sf &lt;- st_read(con, query = "
  WITH executed_evictions AS (
    SELECT DISTINCT(i.indexnumberid), w.executiondate, i.court
    FROM oca_index i
    JOIN oca_warrants w ON i.indexnumberid = w.indexnumberid
    WHERE w.executiondate &gt;= MAKE_DATE(2020,1,1) 
      AND w.executiondate &lt;= MAKE_DATE(2025,12,31)
      AND i.classification IN ('Holdover', 'Non-Payment')
      AND (i.propertytype = 'Residential' OR i.propertytype IS NULL)
      AND w.executiondate IS NOT NULL
  )
  SELECT e.*, ST_TRANSFORM(a.geom, 2263)
  FROM executed_evictions e
  JOIN oca_addresses a on e.indexnumberid = a.indexnumberid
  WHERE a.geom IS NOT NULL
")

### Boundary Files ###
# NYC Boundary via borough boundary union
nyc &lt;- read_sf("https://services5.arcgis.com/GfwWNkhOj9bNBqoJ/arcgis/rest/services/NYC_Borough_Boundary/FeatureServer/0/query?where=1=1&outFields=*&outSR=4326&f=pgeojson") |&gt; 
  st_transform(2263) |&gt; 
  st_make_valid() |&gt; 
  st_union()

# NYS Assembly
nysad &lt;- read_sf("https://services6.arcgis.com/EbVsqZ18sv1kVJ3k/ArcGIS/rest/services/NYS_Assembly_Districts/FeatureServer/0/query?where=0%3D0&outFields=*&f=geojson") |&gt; 
  st_transform(2263) |&gt; 
  st_make_valid()

# NYS Senate
nyss &lt;- read_sf("https://services6.arcgis.com/EbVsqZ18sv1kVJ3k/ArcGIS/rest/services/NYS_Senate_Districts/FeatureServer/0/query?where=0%3D0&outFields=*&f=geojson") |&gt; 
  st_transform(2263) |&gt; 
  st_make_valid()

# NYC Council
nyc_council &lt;- read_sf("https://services5.arcgis.com/GfwWNkhOj9bNBqoJ/arcgis/rest/services/NYC_City_Council_Districts/FeatureServer/0/query?where=1=1&outFields=*&outSR=4326&f=pgeojson") |&gt; 
  st_transform(2263) |&gt; 
  st_make_valid()

# NYC Council members
nyc_council_members &lt;- soc_read(
  "https://data.cityofnewyork.us/City-Government/City-Council-Members-1999-to-Present-/uvw5-9znb.json"
) |&gt; 
  # Filter to current term
  filter(Sys.Date() %within% interval(start = term_start, end = term_end))

# Join CMs to spatial file
nyc_council &lt;- nyc_council |&gt; 
  left_join(nyc_council_members |&gt; 
              select(name, district),
            by = join_by(CounDist == district)) |&gt; 
  # Designate Vacant seats
  mutate(name = replace_na(name, "Vacant"))

# NYC Boundaries via Borough union
bb &lt;- read_sf("https://services5.arcgis.com/GfwWNkhOj9bNBqoJ/arcgis/rest/services/NYC_Borough_Boundary/FeatureServer/0/query?where=1=1&outFields=*&outSR=4326&f=pgeojson") |&gt; 
  st_transform(2263) |&gt; 
  st_make_valid() |&gt; 
  st_union()

# NYS Counties
nys_counties &lt;- read_sf("https://services6.arcgis.com/EbVsqZ18sv1kVJ3k/ArcGIS/rest/services/NYS_Civil_Boundaries/FeatureServer/2/query?where=0%3D0&outFields=*&f=geojson") |&gt; 
  st_transform(2263)

# Separate out upstate / downstate
nysad_downstate &lt;- st_filter(nysad, bb, .predicate = st_intersects)

nysad_upstate &lt;- st_filter(nysad, bb, .predicate = st_disjoint)

nyss_downstate &lt;- st_filter(nyss, bb, .predicate = st_intersects)

nyss_upstate &lt;- st_filter(nyss, bb, .predicate = st_disjoint)

